import { useTreeSelect } from '@dreadnought/react/logic';
type Node = { id: string; label: string; children?: readonly Node[] };
const records: readonly Node[] = [{ id: 'front', label: 'Frontend' }];
export function Example() { const tree = useTreeSelect({ records, getKey: node => node.id, getChildren: node => node.children, getLabel: node => node.label }); return <button onClick={() => tree.select('front')}>{tree.tags[0]?.label ?? 'Выбрать'}</button>; }
